	ctx := context.Background()

	syncedNew, syncedRenamed, err := repo.SyncRulesFromShadow(ctx, 61, 222, "tester")
	if err != nil {
		t.Fatalf("SyncRulesFromShadow failed: %v", err)
	}
	if syncedNew != 2 || syncedRenamed != 0 {
		t.Fatalf("expected syncedNew=2 (paymentMethod + extraPayload), syncedRenamed=0; got new=%d renamed=%d", syncedNew, syncedRenamed)
	}

	// Verify customized snake_case columns were NOT overwritten or duplicated
	var billCols []string
	if err := db.Raw(`SELECT target_column FROM mapping_rule_master WHERE master_binding_id = 61 AND mapping_v2_id = 101 ORDER BY id`).Scan(&billCols).Error; err != nil {
		t.Fatalf("query bill_id rules: %v", err)
	}
	if len(billCols) != 1 || billCols[0] != "bill_id" {
		t.Fatalf("expected [bill_id] preserved for mapping_v2_id=101, got %+v", billCols)
	}

	// Verify newly synced rules have status='pending' and deterministic MIN(id)
	var newRow struct {
		MappingV2ID int64  `gorm:"column:mapping_v2_id"`
		Status      string `gorm:"column:status"`
		CreatedBy   string `gorm:"column:created_by"`
	}
	if err := db.Raw(`SELECT mapping_v2_id, status, created_by FROM mapping_rule_master WHERE master_binding_id = 61 AND target_column = 'paymentMethod'`).Scan(&newRow).Error; err != nil {
		t.Fatalf("query paymentMethod rule: %v", err)
	}
	if newRow.MappingV2ID != 103 || newRow.Status != "pending" || newRow.CreatedBy != "shadow-sync" {
		t.Fatalf("expected paymentMethod v2_id=103 status='pending' created_by='shadow-sync', got %+v", newRow)
	}

